"""Shared validation for model-group configuration."""

from __future__ import annotations

import re
from typing import Any, Dict, List, Mapping

from rasa.exceptions import ValidationError
from rasa.shared.constants import (
    MODEL_GROUP_ID_CONFIG_KEY,
    MODELS_CONFIG_KEY,
    SECRET_DATA_FORMAT_PATTERN,
    SENSITIVE_DATA,
)

_API_KEY_ENV_CONFIG_KEY = "api_key_env"
_API_KEY_ENV_MIGRATION = (
    "which is no longer supported. Replace it with 'api_key: ${ENV_VAR_NAME}'."
)


def validate_model_group_credentials(
    model_groups: List[Dict[str, Any]],
) -> None:
    """Validate that model-group credentials use environment variables.

    Rejects the removed ``api_key_env`` key and requires every present
    :data:`~rasa.shared.constants.SENSITIVE_DATA` value to be exactly
    ``${ENV_VAR_NAME}``. Nested mappings (for example Azure ``oauth``) are
    checked with the same rule.

    Raises:
        ValidationError: When a model entry is not a mapping, still uses
            ``api_key_env``, or stores a sensitive value that is not exactly
            ``${ENV_VAR_NAME}``. Error messages never include the configured
            secret value.
    """
    for model_group in model_groups:
        model_group_id = model_group[MODEL_GROUP_ID_CONFIG_KEY]
        for model_config in model_group[MODELS_CONFIG_KEY]:
            if not isinstance(model_config, Mapping):
                raise ValidationError(
                    code=(
                        "engine.validation."
                        "validate_model_group_configuration_setup."
                        "model_entry_must_be_mapping"
                    ),
                    event_info=(
                        f"Each entry under 'models' in model group "
                        f"'{model_group_id}' must be a mapping of provider "
                        f"settings."
                    ),
                    model_group_id=model_group_id,
                )
            if _API_KEY_ENV_CONFIG_KEY in model_config:
                raise ValidationError(
                    code=(
                        "engine.validation."
                        "validate_model_group_configuration_setup."
                        "api_key_env_not_supported"
                    ),
                    event_info=(
                        f"Model group '{model_group_id}' uses "
                        f"'{_API_KEY_ENV_CONFIG_KEY}', {_API_KEY_ENV_MIGRATION}"
                    ),
                    key=_API_KEY_ENV_CONFIG_KEY,
                    model_group_id=model_group_id,
                )
            _validate_sensitive_values(model_config, model_group_id)


def _validate_sensitive_values(
    config: Mapping[str, Any],
    model_group_id: str,
) -> None:
    """Reject literal or malformed sensitive values, including nested maps."""
    items_to_check = list(config.items())
    while items_to_check:
        key, value = items_to_check.pop()
        if isinstance(value, Mapping):
            items_to_check.extend(value.items())
            continue
        if key not in SENSITIVE_DATA:
            continue
        if isinstance(value, str):
            if not re.fullmatch(SECRET_DATA_FORMAT_PATTERN, value):
                raise ValidationError(
                    code=(
                        "engine.validation."
                        "validate_model_group_configuration_setup."
                        "sensitive_key_string_value_must_be_set_as_env_var"
                    ),
                    event_info=(
                        f"You defined the '{key}' in model group "
                        f"'{model_group_id}' as a "
                        f"string. The '{key}' must be set as an "
                        f"environment variable. Please update your config."
                    ),
                    key=key,
                    model_group_id=model_group_id,
                )
        else:
            raise ValidationError(
                code=(
                    "engine.validation."
                    "validate_model_group_configuration_setup."
                    "sensitive_key_must_be_set_as_env_var"
                ),
                event_info=(
                    f"You should define the '{key}' in model group "
                    f"'{model_group_id}' using the "
                    "environment variable syntax - "
                    "${ENV_VARIABLE_NAME}. Please update your config."
                ),
                key=key,
                model_group_id=model_group_id,
            )
